            start++;
            continue;
        }

        dir = 0; // start facing north
        bool facedNorthInBetween = false;
        int i = start;

        // Process commands until we return to north at the end
        while (i < n) {
            if (s[i] == 'R') {
                dir = (dir + 1) % 4;
            } else if (s[i] == 'L') {
                dir = (dir + 3) % 4;
            }

            i++;

            // Check if we've returned to north
            if (dir == 0) {
                // Check if we faced north in between (excluding start and this end)
                if (!facedNorthInBetween) {
                    ans++;
                }
                // Move start to the next position after this sequence
                start = i;
                break;
            }

            // Mark if we faced north in between (not at start)
            if (dir == 0) {
                facedNorthInBetween = true;
            }
        }

        // If we reached end without returning to north, break
        if (i >= n && dir != 0) {
            break;
        }
    }

    cout << ans << "\n";
