        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String commands = br.readLine().trim();

        int count = 0;
        int dir = 0; // 0: north, 1: east, 2: south, 3: west

        for (int i = 0; i < commands.length(); i++) {
            // Reset for each potential start
            dir = 0;
            boolean northInBetween = false;

            for (int j = i; j < commands.length(); j++) {
                char c = commands.charAt(j);
                if (c == 'R') {
                    dir = (dir + 1) % 4;
                } else { // 'L'
                    dir = (dir + 3) % 4; // equivalent to -1 mod 4
                }

                if (dir == 0 && j != i) {
                    // Facing north at intermediate position (not start)
                    northInBetween = true;
                    break; // This sequence fails, no need to continue
                }

                if (dir == 0 && j != i) {
                    // This condition is already handled above, but just in case
                }
            }

            // Check if this sequence ends facing north with no intermediate north
            // We need to check the full sequence from i to end
            // Re-simulate properly
            dir = 0;
            boolean valid = true;
            for (int j = i; j < commands.length(); j++) {
                char c = commands.charAt(j);
                if (c == 'R') {
                    dir = (dir + 1) % 4;
                } else {
                    dir = (dir + 3) % 4;
                }

                if (dir == 0 && j != commands.length() - 1) {
                    // Intermediate north (not at end)
                    valid = false;
                    break;
                }
            }
            if (valid && dir == 0 && (commands.length() - i) > 0) {
                // Found a valid sequence from i to end
                count++;
            }
        }

        System.out.println(count);
    }
}

